const match = require('@unblockneteasemusic/server');
const logger = require('../src/logger');

/** * 通过unm音源获取音乐URL
 * @param {string} id - 网易云音乐歌曲ID
 * @returns {string|null} 音乐URL或null
 */

module.exports = {
    async unm(id) {
        try {
            // 免 Cookie 的音源：kugou(酷狗) > kuwo(酷我) > bodian(波点) > bilibili
            // 实测酷狗 CDN 给完整 320k，酷我偶尔只给片段
            const sources = ['kugou', 'bodian', 'kuwo', 'bilibili'];
            const response = await match(id, sources);
            logger.info(`unm match ${id} → source=${response?.source} url=${response?.url ? response.url.slice(0,80)+'...' : 'null'}`);
            if (response && response.url) {
                return response.url;
            }
            return null;
        } catch (error) {
            logger.error(`unm error: ${error.message}`);
            return null;
        }
    }
}